        MultipartFile[] files,
        String fitOption,
        boolean autoRotate,
        String colorType,
        CustomPDFDocumentFactory pdfDocumentFactory)
        throws IOException {
    try (PDDocument doc = pdfDocumentFactory.createNewDocument()) {
        appendImages(doc, files, fitOption, autoRotate, colorType);
        return saveToBytes(doc);
    }
